let accountRevision=0,accountPhone='',accountBusy=false,accountEmail='',accountEmailVerified=false;
async function accountAPI(path,method='GET',data){let response;try{response=await fetch('/api/'+path,{method,credentials:'same-origin',headers:method==='GET'?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});}catch{throw Object.assign(Error('সংযোগ পাওয়া যাচ্ছে না। ইন্টারনেট ও সার্ভার চালু আছে কি না দেখুন।'),{offline:true})}let result;try{result=await response.json()}catch{throw Error('অ্যাপের সার্ভার চালু করে localhost লিংক থেকে খুলুন।')}if(!response.ok)throw Object.assign(Error(result.error||'আবার চেষ্টা করুন।'),{status:response.status});return result}
function authIcon(kind){const paths={phone:'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 18h4"/>',lock:'<rect x="4" y="10" width="16" height="11" rx="3"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',person:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3"/>'};return '<svg viewBox="0 0 24 24" aria-hidden="true">'+paths[kind]+'</svg>'}
function authScreen(register=false,message=''){const developerFooter=document.querySelector('.developer-footer');if(developerFooter)developerFooter.hidden=true;if(typeof reportSearch!=='undefined'){reportSearch='';reportFilter='all';reportExpenseCategory='all'}let registrationPhoto='',photoPending=false;db={people:[],entries:[]};accountPhone='';accountEmail='';accountEmailVerified=false;if(typeof syncConflict!=='undefined')syncConflict=null;if(typeof offlineState!=='undefined')offlineState=null;try{localStorage.setItem('dailytally-locked','1');localStorage.removeItem('dailytally-active')}catch{}document.querySelector('#sync-status')?.remove();document.body.classList.add('is-auth');document.querySelector('#nav').innerHTML='';document.querySelector('#user-profile').innerHTML='';const action=register?'অ্যাকাউন্ট তৈরি করুন':'লগইন করুন';document.querySelector('#app').innerHTML='<section class="auth-section"><div class="auth-welcome"><span class="auth-emblem auth-logo"><img src="data:image/png;base64," width="64" height="64" alt="DailyTally"></span><span class="auth-eyebrow">আপনার হিসাব, এক জায়গায়</span><h2>'+(register?'শুরু হোক সহজ হিসাব':'স্বাগতম')+'</h2><p>'+(register?'নিজের অ্যাকাউন্ট তৈরি করে প্রতিদিনের হিসাব রাখুন।':'আপনার DailyTally অ্যাকাউন্টে প্রবেশ করুন।')+'</p></div><form id="auth-form">'+(register?'<label for="auth-name">আপনার নাম</label><div class="auth-input">'+authIcon('person')+'<input id="auth-name" name="name" placeholder="আপনার পুরো নাম" maxlength="50" autocomplete="name" required></div><label class="auth-photo-picker" for="auth-photo"><span id="auth-photo-preview" class="auth-photo-preview">'+authIcon('person')+'</span><span><strong>প্রোফাইল ছবি যোগ করুন</strong><small>ঐচ্ছিক · JPG, PNG, WebP · সর্বোচ্চ ১ MB</small></span><input class="auth-photo-file" id="auth-photo" name="registrationPhotoFile" type="file" accept="image/png,image/jpeg,image/webp"></label>':'')+(register?'<label for="auth-email">ইমেইল</label><div class="auth-input"><span class="email-field-mark" aria-hidden="true">@</span><input id="auth-email" name="email" type="email" autocomplete="email" placeholder="you@example.com" maxlength="254" required></div>':'')+'<label for="auth-phone">মোবাইল নম্বর</label><div class="auth-input">'+authIcon('phone')+'<input id="auth-phone" name="phone" type="tel" inputmode="tel" autocomplete="tel" placeholder="01XXXXXXXXX" required maxlength="20"></div><label for="auth-password">পাসওয়ার্ড</label><div class="auth-input">'+authIcon('lock')+'<input id="auth-password" name="password" type="password" placeholder="'+(register?'কমপক্ষে ৮ অক্ষর':'আপনার পাসওয়ার্ড')+'" minlength="8" maxlength="128" autocomplete="'+(register?'new-password':'current-password')+'" required><button class="auth-reveal" type="button" data-reveal="auth-password" aria-label="পাসওয়ার্ড দেখুন" aria-pressed="false">দেখুন</button></div>'+(register?'<label for="auth-confirm">পাসওয়ার্ড নিশ্চিত করুন</label><div class="auth-input">'+authIcon('lock')+'<input id="auth-confirm" name="confirm" type="password" placeholder="পাসওয়ার্ড আবার লিখুন" minlength="8" maxlength="128" autocomplete="new-password" required><button class="auth-reveal" type="button" data-reveal="auth-confirm" aria-label="পাসওয়ার্ড দেখুন" aria-pressed="false">দেখুন</button></div>':'')+'<p class="danger" id="auth-error" role="alert"></p><button class="primary" id="auth-submit"><span>'+action+'</span><span aria-hidden="true">→</span></button></form><div class="auth-divider"><span>'+(register?'আগেই অ্যাকাউন্ট আছে?':'DailyTally-তে নতুন?')+'</span></div><button id="auth-switch" type="button">'+(register?'লগইন করুন':'নতুন অ্যাকাউন্ট খুলুন')+'</button><p class="auth-note">মোবাইল নম্বর ও পাসওয়ার্ডে প্রবেশ করুন।<br>SMS যাচাই প্রয়োজন নেই।</p></section>';restoreMobileField(register);addDeviceSignIn(register);document.querySelector('#auth-error').textContent=message;document.querySelectorAll('[data-reveal]').forEach(button=>button.onclick=()=>{const input=document.getElementById(button.dataset.reveal),show=input.type==='password';input.type=show?'text':'password';button.textContent=show?'লুকান':'দেখুন';button.setAttribute('aria-pressed',String(show));button.setAttribute('aria-label',show?'পাসওয়ার্ড লুকান':'পাসওয়ার্ড দেখুন')});document.querySelector('#auth-switch').onclick=()=>authScreen(!register);if(typeof addRecoveryLink==='function')addRecoveryLink(register);if(typeof addSocialSignIn==='function')void addSocialSignIn(register);if(typeof checkSocialCompletion==='function')queueMicrotask(()=>void checkSocialCompletion());if(register)document.querySelector('#auth-photo').onchange=async event=>{const file=event.target.files[0],error=document.querySelector('#auth-error');if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>1048576){error.textContent='সর্বোচ্চ ১ MB আকারের JPG, PNG বা WebP ছবি দিন।';event.target.value='';return}photoPending=true;document.querySelector('#auth-submit').disabled=true;document.querySelector('#auth-switch').disabled=true;error.textContent='';try{const photo=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});if(!validProfile({name:'',photo}))throw Error();await new Promise((resolve,reject)=>{const image=new Image();image.onload=resolve;image.onerror=reject;image.src=photo});registrationPhoto=photo;document.querySelector('#auth-photo-preview').innerHTML=profileAvatar({photo});}catch{error.textContent='ছবিটি পড়া যায়নি। অন্য ছবি বাছুন।';event.target.value='';}finally{photoPending=false;document.querySelector('#auth-submit').disabled=false;document.querySelector('#auth-switch').disabled=false}};document.querySelector('#auth-form').onsubmit=async event=>{event.preventDefault();if(photoPending)return;const form=event.target,values=Object.fromEntries(new FormData(form)),error=document.querySelector('#auth-error');if(register&&values.password!==values.confirm){error.textContent='দুটি পাসওয়ার্ড মিলছে না।';return}const button=document.querySelector('#auth-submit');button.disabled=true;button.setAttribute('aria-busy','true');button.textContent=register?'অ্যাকাউন্ট তৈরি হচ্ছে…':'লগইন হচ্ছে…';document.querySelector('#auth-switch').disabled=true;error.textContent='';try{if(register){values.photo=registrationPhoto;delete values.registrationPhotoFile;delete values.confirm}await accountAPI(register?'register':'login','POST',values);form.reset();await loadAccount()}catch(e){error.textContent=e.message;button.disabled=false;button.removeAttribute('aria-busy');button.textContent=action;document.querySelector('#auth-switch').disabled=false}}}

async function loadAccount(){const [session,result]=await Promise.all([accountAPI('session'),accountAPI('data')]);if(!valid(result.data))throw Error('হিসাবের তথ্য পড়া যায়নি।');rememberMobile(session.phone);accountEmail=session.email||'';accountEmailVerified=!!session.emailVerified;await hydrateAccount(session,result);tab='ড্যাশবোর্ড';reportStart='';reportEnd='';render();document.body.classList.remove('is-auth');if(typeof autoServerBackupOnOpen==='function')void autoServerBackupOnOpen();if(typeof restoreReminderNotifications==='function')void restoreReminderNotifications();if(typeof location!=='undefined'&&new URLSearchParams(location.search).get('reminders')==='1'){history.replaceState(null,'',location.pathname);openReminders()}}
async function startAuth(){if(deviceLoginPreference()){try{await accountAPI('logout','POST',{})}catch{}authScreen();return}document.querySelector('#app').innerHTML='<section>লোড হচ্ছে…</section>';try{if(typeof location!=='undefined'&&new URLSearchParams(location.search).get('social')==='complete'){try{await accountAPI('logout','POST',{})}catch{}authScreen();return}if(typeof location!=='undefined'&&new URLSearchParams(location.search).get('social')==='success'){localStorage.removeItem('dailytally-locked');history.replaceState(null,'',location.pathname)}if(localStorage.getItem('dailytally-locked')){try{await accountAPI('logout','POST',{})}catch{}authScreen();return}await loadAccount()}catch(error){if(error.offline&&await resumeOfflineAccount())return;authScreen(false,error.status===401?'':error.message)}}
async function saveAccount(){await persistAccountData()}
async function logoutAccount(){if(accountBusy||!await lockLocalAccount())return;try{await accountAPI('logout','POST',{})}catch{}authScreen()}
function showPasswordChange(){const dialog=document.createElement('dialog');dialog.className='transaction-dialog';dialog.setAttribute('aria-labelledby','password-settings-title');dialog.innerHTML='<div class="dialog-top"><span id="password-settings-title">পাসওয়ার্ড পরিবর্তন</span><button type="button" aria-label="পপআপ বন্ধ করুন">✕</button></div><section><form id="password-settings-form"><fieldset><label>বর্তমান পাসওয়ার্ড<input name="currentPassword" type="password" autocomplete="current-password" maxlength="128" required></label><label>নতুন পাসওয়ার্ড<input name="newPassword" type="password" autocomplete="new-password" minlength="8" maxlength="128" required></label><label>নতুন পাসওয়ার্ড আবার দিন<input name="confirmPassword" type="password" autocomplete="new-password" minlength="8" maxlength="128" required></label><p id="password-error" role="alert" class="danger"></p><button class="primary">পাসওয়ার্ড পরিবর্তন করুন</button></fieldset></form></section>';dialog.querySelector('.dialog-top button').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());document.querySelector('#app').append(dialog);dialog.querySelector('form').onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.target)),error=dialog.querySelector('#password-error'),button=event.target.querySelector('button');if(values.newPassword!==values.confirmPassword){error.textContent='দুটি পাসওয়ার্ড মিলছে না।';return}button.disabled=true;try{await accountAPI('password','POST',values);event.target.reset();dialog.close();alert('পাসওয়ার্ড পরিবর্তন হয়েছে। অন্য ডিভাইসের লগইন বন্ধ করা হয়েছে।')}catch(e){error.textContent=e.message;button.disabled=false}};dialog.showModal()}
